namespace Mpq;

/// <summary>
/// The write half of MPQ's block cipher. <see cref="MpqCrypt"/> has the crypt table, the
/// filename hash and the decryptor; encryption is only ever needed by the writer, so it lives
/// here rather than in the reader's file.
/// </summary>
/// <remarks>
/// The crypt table is rebuilt here because <see cref="MpqCrypt"/> keeps its copy private.
/// It is 14 lines of frozen spec and both copies are generated by the same recurrence, so they
/// cannot drift — but once the reader and writer branches are merged, the two should become
/// one table with an <c>Encrypt</c> next to <c>Decrypt</c>.
/// </remarks>
internal static class MpqWriteCrypt {
	static readonly uint[] table = Build();

	static uint[] Build() {
		var t = new uint[0x500];
		uint seed = 0x00100001;
		for (int i = 0; i < 0x100; i++) {
			for (int j = 0; j < 5; j++) {
				seed = (seed * 125 + 3) % 0x2AAAAB;
				uint hi = (seed & 0xFFFF) << 16;
				seed = (seed * 125 + 3) % 0x2AAAAB;
				t[i + j * 0x100] = hi | (seed & 0xFFFF);
			}
		}
		return t;
	}

	/// <summary>
	/// Encrypts in place, DWORD-wise — the exact inverse of <see cref="MpqCrypt.Decrypt"/>.
	/// Note the seed is advanced from the <em>plaintext</em> dword, which is why this is not
	/// symmetric with the decryptor and cannot be written as one shared routine.
	/// </summary>
	public static void Encrypt(Span<byte> data, uint key) {
		uint seed = 0xEEEEEEEE;
		int dwords = data.Length / 4;
		for (int i = 0; i < dwords; i++) {
			seed += table[0x400 + (key & 0xFF)];
			var slot = data.Slice(i * 4, 4);
			uint plain = BitConverter.ToUInt32(slot);
			BitConverter.TryWriteBytes(slot, plain ^ (key + seed));
			key = ((~key << 21) + 0x11111111) | (key >> 11);
			seed = plain + seed + (seed << 5) + 3;
		}
	}
}
